"""Generate one word-count- and position-conditioned, language-free book."""
from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path
import random

from vs import corpus, dsl, ivtff, redteam
from vs.ivtff import Line, Page

ROOT = Path(__file__).resolve().parent
DESIGN = json.loads((ROOT / "design.json").read_text())


def line_bin(n):
    if n <= 4:
        return str(n)
    if n <= 7:
        return "5–7"
    return "8–11" if n <= 11 else "12+"


def length_bin(size):
    if size <= 3:
        return "1–3"
    if size <= 6:
        return "4–6"
    return "7+"


def slot(index, n):
    if index == 0:
        return "first"
    if index == n - 1:
        return "last"
    return "interior"


def phase(index, n):
    if index == 0:
        return "first"
    if index == n - 1:
        return "last"
    return "middle"


def length_keys(group, role):
    return tuple(dict.fromkeys(((group, role), ("all", role), ("all", "all"))))


def transition_keys(group, role, size, where, previous):
    length = length_bin(size)
    layered = (
        (group, role, length, where, previous),
        (group, role, "all", where, previous),
        (group, role, "all", where, None),
        ("all", role, "all", where, previous),
        ("all", role, "all", where, None),
        ("all", "all", "all", where, previous),
        ("all", "all", "all", where, None),
    )
    return tuple(dict.fromkeys(layered))


class Table:
    def __init__(self, informative_length=True):
        self.informative_length = informative_length
        self.lengths = defaultdict(Counter)
        self.transitions = defaultdict(Counter)
        self.seen = 0

    def add_line(self, words):
        n = len(words)
        group = line_bin(n) if self.informative_length else "all"
        for index, word in enumerate(words):
            if ivtff.uncertain(word):
                continue
            glyphs = ivtff.segment(word, "eva-basic")
            if not glyphs or not all(glyph.isascii() and glyph.isalpha() for glyph in glyphs):
                continue
            role = slot(index, n)
            self.seen += 1
            for key in length_keys(group, role):
                self.lengths[key][len(glyphs)] += 1
            for k, glyph in enumerate(glyphs):
                before = glyphs[k - 1] if k else None
                for key in transition_keys(group, role, len(glyphs), phase(k, len(glyphs)), before):
                    self.transitions[key][glyph] += 1

    @staticmethod
    def cache(counters, min_count):
        return {key: tuple(zip(*sorted(values.items()), strict=True))
                for key, values in counters.items() if sum(values.values()) >= min_count}

    def freeze(self):
        self.length_choices = self.cache(self.lengths, 8)
        self.transition_choices = self.cache(self.transitions, 5)

    @staticmethod
    def draw(choices, keys, rng):
        for key in keys:
            if key in choices:
                items, weights = choices[key]
                return rng.choices(items, weights=weights)[0]
        raise ValueError(("insufficient training data", keys))

    def word(self, index, n, rng):
        role = slot(index, n)
        group = line_bin(n) if self.informative_length else "all"
        size = self.draw(self.length_choices, length_keys(group, role), rng)
        glyphs = []
        previous = None
        for k in range(size):
            keys = transition_keys(group, role, size, phase(k, size), previous)
            previous = self.draw(self.transition_choices, keys, rng)
            glyphs.append(previous)
        return "".join(glyphs)


def learn(training, units=None, informative_length=True):
    model = Table(informative_length)
    for page in training:
        for line in page.lines:
            if line.words and (units is None or line.unit in units):
                model.add_line(line.words)
    model.freeze()
    return model


def generate(model, layout, seed, forbidden):
    rng = random.Random(seed)
    book = []
    rejected = 0
    for n in layout:
        line = []
        for index in range(n):
            for _ in range(256):
                word = model.word(index, n, rng)
                if len(line) < 3 or (*line[-3:], word) not in forbidden:
                    line.append(word)
                    break
                rejected += 1
            else:
                raise RuntimeError("four-word rejection budget exhausted")
        book.append(line)
    return book, rejected


def readout(book, all_pages, practice_ids, spec, with_permutation=True):
    it = iter(book)
    layout = []
    for page in all_pages:
        imitation = Page(page.id, page.order, dict(page.meta))
        for line in page.lines:
            words = list(next(it)) if line.words else []
            assert len(words) == len(line.words)
            imitation.lines.append(Line(line.id, line.page, line.n, line.unit, line.subtype,
                                        words, line.para_start, line.para_end))
        if page.id in practice_ids:
            layout.append(imitation)
    assert next(it, None) is None
    tokens = dsl.select(dsl.tokens(layout), spec.get("select"))
    ratio_spec = spec["statistic"]["ratio"]
    counts = {}
    for group, key in (("label_first", "of"), ("paragraph_first", "to")):
        chosen = dsl.select(tokens, ratio_spec[key])
        counts[group] = [sum(dsl.feature({"prefix": 1}, t["w"]) == ["o"] for t in chosen), len(chosen)]
    value = dsl.statistic(spec["statistic"], tokens, tokens)
    return {"counts": counts, "ratio": value,
            "spec_test": dsl.evaluate(spec, layout) if with_permutation else None}


def main():
    from vs import registry
    target = registry.get(DESIGN["target"])
    assert target["verdict"] == "ESTABLISHED"
    spec = target["detail"]["spec"]
    train, ev = corpus.split_pages("practice")
    practice_ids = {p.id for p in ev}
    all_pages = corpus.pages()
    true_layout = [len(line.words) for page in all_pages for line in page.lines if line.words]
    forbidden = redteam._manuscript_4grams()
    core = learn(train)
    layout_agnostic = learn(train, informative_length=False)
    paragraph_only = learn(train, units={"P"})
    report = {"layout_lines": len(true_layout), "layout_words": sum(true_layout),
              "training_pages": len(train), "evaluation_pages": len(ev),
              "seed": DESIGN["primary_seed"], "models": {}}
    for name, model in (("primary", core), ("without_line_length", layout_agnostic),
                        ("paragraph_only", paragraph_only)):
        book, rejections = generate(model, true_layout, DESIGN["primary_seed"], forbidden)
        metrics = readout(book, all_pages, practice_ids, spec)
        report["models"][name] = {
            "training_certainty_filtered_words": model.seen, "four_gram_rejections": rejections,
            "public_practice": metrics,
        }
        if name != "primary":
            continue
        output = json.dumps(book, separators=(",", ":")) + "\n"
        (ROOT / "frozen-book.json").write_text(output)
        report["primary_book_sha256"] = sha256(output.encode()).hexdigest()
        report["models"][name]["heldout_independent_public_seed_checks"] = []
        for seed in DESIGN["public_diagnostic_seeds"]:
            generated, removed = generate(model, true_layout, seed, forbidden)
            report["models"][name]["heldout_independent_public_seed_checks"].append({
                "seed": seed, "four_gram_rejections": removed,
                **readout(generated, all_pages, practice_ids, spec, with_permutation=False),
            })
    (ROOT / "public-diagnostics.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

