"""Explain the frozen onset ratios from fitted tables and public layout overlap."""
import json
from collections import Counter, defaultdict
from pathlib import Path

from vs import corpus, dsl
from generate_book import learn, line_bin, length_keys, transition_keys


ROOT = Path(__file__).resolve().parent
SIZES = (1, 2, 3, 4, 6, 9, 13)


def distribution(choices, keys):
    items, weights = next(choices[k] for k in keys if k in choices)
    total = sum(weights)
    return [(item, weight / total) for item, weight in zip(items, weights, strict=True)]


def expected_o(model, n):
    role = "first"
    group = line_bin(n) if model.informative_length else "all"
    sizes = distribution(model.length_choices, length_keys(group, role))
    return sum(
        probability * dict(distribution(
            model.transition_choices, transition_keys(group, role, size, "first", None),
        )).get("o", 0.0)
        for size, probability in sizes
    )


def exposures(pages, exact):
    grouped = defaultdict(lambda: {"L": Counter(), "P": Counter()})
    tokens = dsl.select(dsl.tokens(pages), {"unit": ["L", "P"], "position": "line_initial", "certain": True})
    for token in tokens:
        key = (token["page"], token["n"]) if exact else line_bin(token["n"])
        grouped[key][token["unit"]][dsl.feature({"prefix": 1}, token["w"]) == ["o"]] += 1
    return grouped


def matched_support(pages):
    rows = exposures(pages, True)
    overlap = {key: record for key, record in rows.items()
               if all(sum(record[kind].values()) > 0 for kind in ("L", "P"))}
    out = {}
    for unit in ("L", "P"):
        group = sum((row[unit] for row in overlap.values()), Counter())
        out[unit] = {"valid_heads": sum(group.values()), "o_heads": group[True]}
    return {"matched_page_and_exact_line_length_cells": len(overlap),
            "represented_panels": len({page for page, _ in overlap}), "counts": out}


def main():
    train, evaluation = corpus.split_pages("practice")
    empirical = exposures(evaluation, False)
    models = {"primary": learn(train), "paragraph_only": learn(train, units={"P"}),
              "without_line_length": learn(train, informative_length=False)}
    output = {"strict_real_exposure_support": {},
              "model_expected_onset_rates_given_real_evaluation_exposure": {}}
    for label, model in models.items():
        probs = {line_bin(n): expected_o(model, n) for n in SIZES}
        horizon = {
            unit: sum(sum(counts[unit].values()) * probs[key] for key, counts in empirical.items())
            / sum(sum(counts[unit].values()) for counts in empirical.values())
            for unit in ("L", "P")
        }
        output["model_expected_onset_rates_given_real_evaluation_exposure"][label] = {
            "first_glyph_o_by_line_length_bin": probs, "expected_rate_by_unit": horizon,
            "ratio_of_expected_rates": horizon["L"] / horizon["P"],
        }
    for edition in ("zl", "it", "rf"):
        train, ev = corpus.split_pages("practice", edition)
        output["strict_real_exposure_support"][edition] = {
            "public_training": matched_support(train), "public_evaluation": matched_support(ev),
        }
    (ROOT / "expected-chain-onset.json").write_text(json.dumps(output, indent=2, ensure_ascii=False) + "\n")
    print(json.dumps(output, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

