"""Public-practice exposure of label and paragraph onsets to line token counts."""

import argparse
from bisect import bisect_left
from collections import Counter, defaultdict
from dataclasses import dataclass
from fractions import Fraction
import json
from pathlib import Path

from vs import corpus, dsl, ivtff


BUCKETS = ("1", "2", "3", "4", "5–7", "8–11", "12+")
UPPER_BOUNDS = (1, 2, 3, 4, 7, 11)
TARGET_UNITS = ("L", "P")


@dataclass(frozen=True)
class Count:
    lines: int
    starts_o: int

    @property
    def rate(self):
        return Fraction(self.starts_o, self.lines) if self.lines else None


def exposure(pages):
    """Count literal eligible first words by unit and full parsed line length."""
    result = defaultdict(Counter)
    tokens = dsl.select(dsl.tokens(pages), {"position": "line_initial", "certain": True})
    for token in tokens:
        glyphs = ivtff.segment(token["w"], "eva-basic")
        if glyphs:
            bucket = BUCKETS[bisect_left(UPPER_BOUNDS, token["n"])]
            result[token["unit"], bucket][glyphs[0] == "o"] += 1
    return {(unit, bucket): Count(sum(c.values()), c[True]) for (unit, bucket), c in result.items()}


def combined(table, buckets, unit=None):
    counts = [v for (u, b), v in table.items() if b in buckets and (unit is None or u == unit)]
    return Count(sum(v.lines for v in counts), sum(v.starts_o for v in counts))


def number(value):
    return float(value) if value is not None else None


def observed_row(table, unit):
    total = combined(table, BUCKETS, unit)
    buckets = {}
    for bucket in BUCKETS:
        count = combined(table, (bucket,), unit)
        buckets[bucket] = {"lines": count.lines, "starts_o": count.starts_o,
                           "line_share": number(Fraction(count.lines, total.lines)) if total.lines else None,
                           "observed_rate": number(count.rate)}
    return {"lines": total.lines, "starts_o": total.starts_o,
            "observed_rate": number(total.rate), "buckets": buckets}


def contrast(rates):
    label, paragraph = (rates[u] for u in TARGET_UNITS)
    return {"label_minus_paragraph": number(label - paragraph) if label is not None and paragraph is not None else None,
            "label_divided_by_paragraph": number(label / paragraph) if label is not None and paragraph else None}


def counterfactual(training, evaluation, calibration_unit=None):
    calibration = {bucket: combined(training, (bucket,), calibration_unit) for bucket in BUCKETS}
    supported = {bucket for bucket, count in calibration.items() if count.lines}
    rates = {bucket: calibration[bucket].rate for bucket in supported}
    denominators, expected_rates, observed_rates = {}, {}, {}
    for unit in TARGET_UNITS:
        total = combined(evaluation, BUCKETS, unit)
        covered = combined(evaluation, supported, unit)
        predicted_hits = sum(combined(evaluation, (b,), unit).lines * rate for b, rate in rates.items())
        expected_rates[unit] = predicted_hits / covered.lines if covered.lines else None
        observed_rates[unit] = covered.rate
        denominators[unit] = {
            "evaluation_lines": total.lines, "covered_lines": covered.lines,
            "covered_share": number(Fraction(covered.lines, total.lines)) if total.lines else None,
            "unsupported_evaluation_lines": {b: combined(evaluation, (b,), unit).lines
                                             for b in BUCKETS if b not in supported},
            "expected_starts_o": number(predicted_hits),
            "expected_rate_on_covered_lines": number(expected_rates[unit]),
            "observed_rate_on_covered_lines": number(observed_rates[unit]),
        }
    observed_delta = contrast(observed_rates)
    expected_delta = contrast(expected_rates)
    observed_gap = observed_delta["label_minus_paragraph"]
    expected_gap = expected_delta["label_minus_paragraph"]
    return {
        "calibration_buckets": {bucket: {"training_lines": count.lines, "training_starts_o": count.starts_o,
                                         "training_rate": number(count.rate)}
                                for bucket, count in calibration.items()},
        "evaluation": denominators,
        "expected_contrast_on_covered_lines": expected_delta,
        "observed_contrast_on_covered_lines": observed_delta,
        "expected_fraction_of_observed_absolute_rate_gap":
            expected_gap / observed_gap if expected_gap is not None and observed_gap else None,
    }


def analyze(training, evaluation):
    return {
        "observed": {
            name: {
                "by_unit": {unit: observed_row(table, unit) for unit in TARGET_UNITS},
                "contrast": contrast({unit: combined(table, BUCKETS, unit).rate for unit in TARGET_UNITS}),
                "eligible_lines_by_unit": {unit: combined(table, BUCKETS, unit).lines
                                           for unit in sorted({u for u, _ in table})},
            }
            for name, table in (("training", training), ("evaluation", evaluation))
        },
        "calibration": {
            "pooled_all_units_training": counterfactual(training, evaluation),
            "paragraph_only_training": counterfactual(training, evaluation, "P"),
        },
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, default=Path(__file__).with_name("length-exposure.json"))
    args = parser.parse_args()
    report = {
        "split": "Public project practice split only, no folio-level data in output.",
        "scope": "All manuscript sections, languages and scribal hands, reported separately for ZL and IT.",
        "selection": "Literal first word on each IVTFF line. Exclude uncertain first words without promoting another word.",
        "onset": "First glyph equals o under eva-basic.",
        "exposure": "Full parsed line word count, including uncertain noninitial tokens. Line kind is absent from bucket calibration.",
        "bucket_order": BUCKETS,
        "estimand": "Apply observed training-bucket rates to evaluation L and P exposure weights. "
                    "In each calibration omit unsupported buckets and compare observed rates on the same covered evaluation words. "
                    "Pooled rates include all kinds, including labels, so this is descriptive rather than an independent generator test.",
        "transliterations": {},
    }
    for edition in ("zl", "it"):
        training, evaluation = corpus.split_pages("practice", translit=edition)
        report["transliterations"][edition] = analyze(exposure(training), exposure(evaluation))
    args.out.write_text(json.dumps(report, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
